import{_ as a,o as e,c as i,a2 as s}from"./chunks/framework.CvydjLy7.js";const g=JSON.parse('{"title":"11.8 GraalVM 原生镜像","description":"","frontmatter":{"title":"11.8 GraalVM 原生镜像"},"headers":[{"level":3,"title":"构建前提","slug":"构建前提","link":"#构建前提","children":[]},{"level":3,"title":"编译命令与实测结果","slug":"编译命令与实测结果","link":"#编译命令与实测结果","children":[]},{"level":3,"title":"构建代价","slug":"构建代价","link":"#构建代价","children":[]},{"level":3,"title":"运行时的收益","slug":"运行时的收益","link":"#运行时的收益","children":[]},{"level":3,"title":"封闭世界假设","slug":"封闭世界假设","link":"#封闭世界假设","children":[]},{"level":3,"title":"什么时候值得用","slug":"什么时候值得用","link":"#什么时候值得用","children":[]}],"relativePath":"ch11/08.md","filePath":"ch11/08.md","lastUpdated":1789497795000}'),n={name:"ch11/08.md"};function l(d,t,r,p,o,h){return e(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="_11-8-graalvm-原生镜像" tabindex="-1">11.8 GraalVM 原生镜像 <a class="header-anchor" href="#_11-8-graalvm-原生镜像" aria-label="Permalink to &quot;11.8 GraalVM 原生镜像&quot;">​</a></h1><p>前面所有优化都在 JVM 的框架内做——JVM 还是要启动、还是要加载类。原生镜像（Native Image）走的是另一条路：<strong>把应用编译成一个平台相关的可执行文件，里面不再有 JVM。</strong></p><p>好处很直接：启动时间从秒级降到毫秒级，内存占用显著下降。代价同样直接：构建要几分钟、产物要几十分钟的静态分析、部分动态特性不再可用。</p><h3 id="构建前提" tabindex="-1">构建前提 <a class="header-anchor" href="#构建前提" aria-label="Permalink to &quot;构建前提&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>GraalVM</td><td>25 及以上（本次实测 25.0.4）</td></tr><tr><td>Maven 插件</td><td><code>native-maven-plugin</code>，版本 1.1.8（由父 POM 管理）</td></tr><tr><td>内存</td><td>编译过程比较吃内存，建议 8GB 以上</td></tr></tbody></table><p><code>native-maven-plugin</code> 必须由工程显式声明，父 POM 里只在 <code>pluginManagement</code> 中提供了配置：</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">plugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;org.graalvm.buildtools&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">groupId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;native-maven-plugin&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">artifactId</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">plugin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>不写 <code>&lt;version&gt;</code>，版本从父 POM 的 <code>native-build-tools-plugin.version</code> 继承。</p><h3 id="编译命令与实测结果" tabindex="-1">编译命令与实测结果 <a class="header-anchor" href="#编译命令与实测结果" aria-label="Permalink to &quot;编译命令与实测结果&quot;">​</a></h3><p><code>native:compile</code> 不在 <code>package</code> 阶段里，要显式调用：</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> JAVA_HOME=/path/to/graalvm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mvn</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -Pnative</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -DskipTests</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> package</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> native:compile</span></span></code></pre></div><p>这里有个容易踩的地方：<strong><code>mvn -Pnative package</code> 不会编译原生镜像</strong>。父 POM 的 <code>native</code> profile 里给 <code>spring-boot-maven-plugin</code> 绑了 <code>process-aot</code>，给 <code>native-maven-plugin</code> 绑了 <code>add-reachability-metadata</code>，但没有绑定 <code>compile</code>。只跑 <code>package</code> 的话，得到的还是一个带 AOT 代码的普通 jar——日志里能看到 <code>process-aot</code> 执行了，<code>native:compile</code> 却不见了。</p><h3 id="构建代价" tabindex="-1">构建代价 <a class="header-anchor" href="#构建代价" aria-label="Permalink to &quot;构建代价&quot;">​</a></h3><p>编译输出很简洁：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GraalVM Native Image: Generating &#39;activity-server&#39; (executable)...</span></span>
<span class="line"><span>Build artifacts:</span></span>
<span class="line"><span>Finished generating &#39;activity-server&#39; in 4m 37s.</span></span>
<span class="line"><span>[INFO] BUILD SUCCESS</span></span>
<span class="line"><span>[INFO] Total time:  04:55 min</span></span></code></pre></div><p>本工程 52 个 Java 文件、约 100 个依赖，编译花了 <strong>4 分 37 秒</strong>（连上 Maven 前置阶段共 4 分 55 秒）。这个过程包含几步：</p><ul><li><strong>静态分析</strong>：从 <code>main</code> 入口出发，把能到达的代码全找出来，构建期不可达的代码会被直接删掉</li><li><strong>可达性元数据应用</strong>：把 Spring AOT 生成的提示文件和 <code>graalvm-reachability-metadata</code> 仓库里的元数据合进来</li><li><strong>编译与链接</strong>：生成目标平台的可执行文件</li></ul><p>编译时长与项目规模、依赖数量强相关。Spring Boot 官方对构建环境的要求是至少 8GB 内存，依赖更多、反射更重的项目时间会更长，给到 16GB 更稳妥。所以原生镜像适合放在 CI 里做，不适合开发时反复跑。</p><h3 id="运行时的收益" tabindex="-1">运行时的收益 <a class="header-anchor" href="#运行时的收益" aria-label="Permalink to &quot;运行时的收益&quot;">​</a></h3><p>产物是一个平台相关的可执行文件：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ file target/activity-server</span></span>
<span class="line"><span>target/activity-server: Mach-O 64-bit executable arm64</span></span></code></pre></div><p>两种形态放在一起对比：</p><table tabindex="0"><thead><tr><th>运行形态</th><th>产物</th><th>启动耗时（中位数）</th><th>常驻内存</th></tr></thead><tbody><tr><td>JVM 可执行 jar</td><td>62 MB</td><td>4.80 秒</td><td>546 MB</td></tr><tr><td>GraalVM 原生镜像</td><td>191 MB</td><td>0.268 秒</td><td>167 MB</td></tr></tbody></table><p>原生镜像启动三次：0.357 / 0.268 / 0.266 秒。内存数字是应用就绪后静置 4 秒读数，JVM 侧用的是默认堆参数。</p><p>启动快了约 18 倍，内存降到约三分之一。接口行为完全一致——两种形态下健康检查与 <code>/api/activities</code> 都返回 200，说明这不是一个“跑不起来但很快”的产物。</p><p>要正确理解这里的体积对比。191MB 看起来比 62MB 的 jar 大，但两者不可比：<strong>jar 需要外部 JRE 才能运行</strong>，而原生可执行文件自带运行时。放到镜像里看就反过来了——JVM 路线的基础镜像是 366MB 的 JRE 镜像加应用，原生路线理论上只需要一个近乎空的运行时基础镜像加这 191MB。</p><h3 id="封闭世界假设" tabindex="-1">封闭世界假设 <a class="header-anchor" href="#封闭世界假设" aria-label="Permalink to &quot;封闭世界假设&quot;">​</a></h3><p>原生镜像最大的限制来自 GraalVM 的封闭世界假设：<strong>能到达的代码在构建期就定死，运行期不再有新的类加载。</strong></p><p>GraalVM 本身不认识反射、动态代理、资源加载这些动态行为，需要靠提示文件告诉它。Spring 的 AOT 处理会自动生成这些提示，所以大多数框架层面的问题已经被处理好了。真正需要你注意的是那些会让 <strong>Bean 定义随运行期条件变化</strong>的写法：</p><ul><li><code>@Profile</code> 与 profile 专属配置</li><li><code>@ConditionalOnProperty</code> 与各种 <code>.enabled</code> 开关</li></ul><p>这和 11.4 里 JVM AOT 的限制是同一批——因为原生镜像整条链路都走 AOT，JVM AOT 的限制在这里是加强版：不只是“不生效”，而是<strong>构建期就按某一种条件算死了 Bean 定义</strong>。</p><p>实际判断方法很简单：如果你的应用启动时依赖环境变量、命令行参数来决定“装配哪些 Bean”，那它就不适合原生镜像。反过来，如果装配过程是固定的，只是配置值在变（数据库地址、超时时间这类），原生镜像完全没有问题。</p><h3 id="什么时候值得用" tabindex="-1">什么时候值得用 <a class="header-anchor" href="#什么时候值得用" aria-label="Permalink to &quot;什么时候值得用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>场景</th><th>是否适合</th></tr></thead><tbody><tr><td>Serverless / FaaS，按请求计费</td><td>适合，启动时间是主要成本</td></tr><tr><td>需要快速扩缩容的容器服务</td><td>适合，扩容时的冷启动显著缩短</td></tr><tr><td>常驻服务、实例数固定</td><td>收益有限，JVM 的启动成本只在部署时付一次</td></tr><tr><td>构建环境受限的 CI</td><td>需要评估，编译对内存和时间的消耗不小</td></tr><tr><td>大量使用运行期条件装配</td><td>不适合，需要先改代码结构</td></tr><tr><td>依赖不支持原生镜像的第三方库</td><td>不适合，除非能补齐可达性元数据</td></tr><tr><td>依赖 JVM 生态的动态能力（字节码增强、运行时代理、JMX 动态管理）</td><td>不适合，这些能力在封闭世界里不存在</td></tr></tbody></table><p>还有一点值得知道：<strong>原生镜像和平台绑定得更紧</strong>。可执行文件是平台相关产物，一份构建只能在同架构同系统的机器上跑。</p><hr>`,36)])])}const k=a(n,[["render",l]]);export{g as __pageData,k as default};
